INSERT OR REPLACE INTO "Trip" ("id","userId","title","description","coverImage","startDate","endDate","status","isPublic","slug","budget","currency","createdAt","updatedAt") VALUES ('trip_japan_2024', 'seed_user_demo_001', 'Japan Adventure', 'Two weeks exploring the Land of the Rising Sun - from Tokyo''s neon lights to Kyoto''s ancient temples.', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e', '2024-03-15T00:00:00.000Z', '2024-03-29T00:00:00.000Z', 'COMPLETED', 1, 'japan-adventure-2024', 5000, 'USD', '2026-03-25T23:29:01.172Z', '2026-03-25T23:29:01.172Z');
INSERT OR REPLACE INTO "Memory" ("id","tripId","userId","title","content","date","locationName","locationAddress","latitude","longitude","placeId","category","rating","isPublic","slug","createdAt","updatedAt") VALUES ('entry_tokyo_arrival', 'trip_japan_2024', 'seed_user_demo_001', 'Arriving in Tokyo', '<p>Finally landed at Narita Airport after a 14-hour flight. The efficiency of everything here is remarkable - from the airport trains to the vending machines on every corner. Checked into our hotel in Shinjuku and immediately went out to explore the neon-lit streets. The sensory overload is real!</p>', '2024-03-15T00:00:00.000Z', 'Shinjuku, Tokyo', 'Shinjuku City, Tokyo, Japan', 35.6938, 139.7034, NULL, 'REFLECTION', 5, 0, NULL, '2026-03-25T23:29:01.172Z', '2026-03-25T23:29:01.172Z');
INSERT OR REPLACE INTO "Memory" ("id","tripId","userId","title","content","date","locationName","locationAddress","latitude","longitude","placeId","category","rating","isPublic","slug","createdAt","updatedAt") VALUES ('entry_tsukiji', 'trip_japan_2024', 'seed_user_demo_001', 'Tsukiji Outer Market Food Tour', '<p>Started the day early at Tsukiji Outer Market. Had the freshest sushi I''ve ever tasted - the tuna melted in my mouth. Also tried tamagoyaki (Japanese omelette) fresh off the grill. The vendors were so friendly despite the language barrier.</p>', '2024-03-16T00:00:00.000Z', 'Tsukiji Outer Market', '4 Chome-16-2 Tsukiji, Chuo City, Tokyo', 35.6654, 139.7707, NULL, 'FOOD', 5, 0, NULL, '2026-03-25T23:29:01.172Z', '2026-03-25T23:29:01.172Z');
INSERT OR REPLACE INTO "Memory" ("id","tripId","userId","title","content","date","locationName","locationAddress","latitude","longitude","placeId","category","rating","isPublic","slug","createdAt","updatedAt") VALUES ('entry_kyoto_temple', 'trip_japan_2024', 'seed_user_demo_001', 'Fushimi Inari Shrine', '<p>Walked through thousands of vermillion torii gates at Fushimi Inari. Started early to avoid crowds and it was magical watching the sunrise paint the gates golden. The hike to the top took about 2 hours but the views of Kyoto were worth every step.</p>', '2024-03-20T00:00:00.000Z', 'Fushimi Inari Taisha', '68 Fukakusa Yabunouchicho, Fushimi Ward, Kyoto', 34.9671, 135.7727, NULL, 'ACTIVITY', 5, 0, NULL, '2026-03-25T23:29:01.172Z', '2026-03-25T23:29:01.172Z');
