INSERT OR REPLACE INTO "Trip" ("id","userId","title","description","coverImage","startDate","endDate","status","isPublic","slug","budget","currency","createdAt","updatedAt") VALUES ('trip_iceland_2024', 'seed_user_demo_001', 'Iceland Ring Road', '10 days driving around Iceland''s famous Route 1, chasing waterfalls, glaciers, and the Northern Lights.', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67', '2024-09-10T00:00:00.000Z', '2024-09-20T00:00:00.000Z', 'COMPLETED', 0, 'iceland-ring-road', 4000, 'USD', '2026-03-25T23:29:01.172Z', '2026-03-25T23:29:01.172Z');
INSERT OR REPLACE INTO "Memory" ("id","tripId","userId","title","content","date","locationName","locationAddress","latitude","longitude","placeId","category","rating","isPublic","slug","createdAt","updatedAt") VALUES ('entry_reykjavik', 'trip_iceland_2024', 'seed_user_demo_001', 'First Day in Reykjavik', '<p>Arrived in Reykjavik and picked up our camper van. The air here is so crisp and clean. Walked around the colorful downtown, visited Hallgrímskirkja church and had a delicious lamb soup at a local café. Excited for the adventure ahead!</p>', '2024-09-10T00:00:00.000Z', 'Reykjavik', 'Reykjavik, Iceland', 64.1466, -21.9426, NULL, 'REFLECTION', 4, 0, NULL, '2026-03-25T23:29:01.172Z', '2026-03-25T23:29:01.172Z');
INSERT OR REPLACE INTO "Memory" ("id","tripId","userId","title","content","date","locationName","locationAddress","latitude","longitude","placeId","category","rating","isPublic","slug","createdAt","updatedAt") VALUES ('entry_golden_circle', 'trip_iceland_2024', 'seed_user_demo_001', 'Golden Circle Day Trip', '<p>Did the famous Golden Circle today. Þingvellir National Park was incredible - standing between two tectonic plates! Watched Strokkur geyser erupt every few minutes and got completely soaked by the spray at Gullfoss waterfall. Iceland delivers!</p>', '2024-09-11T00:00:00.000Z', 'Gullfoss Waterfall', 'Gullfoss, Iceland', 64.3271, -20.1199, NULL, 'ACTIVITY', 5, 0, NULL, '2026-03-25T23:29:01.172Z', '2026-03-25T23:29:01.172Z');
INSERT OR REPLACE INTO "Memory" ("id","tripId","userId","title","content","date","locationName","locationAddress","latitude","longitude","placeId","category","rating","isPublic","slug","createdAt","updatedAt") VALUES ('entry_northern_lights', 'trip_iceland_2024', 'seed_user_demo_001', 'Northern Lights Magic', '<p>Finally saw them! We parked the camper van by a remote lake and waited. Around midnight, the sky exploded in green and purple waves. No photo can capture how it felt to witness this natural phenomenon. Tears in my eyes, honestly.</p>', '2024-09-15T00:00:00.000Z', 'Near Akureyri', 'Akureyri, Iceland', 65.6885, -18.1262, NULL, 'ACTIVITY', 5, 0, NULL, '2026-03-25T23:29:01.172Z', '2026-03-25T23:29:01.172Z');
